import type { TodosUseCases } from '../todos/ui/TodosContext/TodosContext'

/** The only place that builds infrastructure: every feature receives its use cases from here. */
export const createTodosUseCases = (apiBaseUrl: string): TodosUseCases => {
  const todos = new HttpTodoGateway(apiBaseUrl)
  return { listTodos: new ListTodos(todos) }
}
import type { TodoGateway } from './TodoGateway'
import type { TodoViewModel } from './TodoViewModel'

export class ListTodos {
  private readonly todos: TodoGateway

  constructor(todos: TodoGateway) {
    this.todos = todos
  }

  async execute(signal?: AbortSignal): Promise<TodoViewModel[]> {
    const records = await this.todos.list(signal)
    return records.map((record) => ({
      id: record.id,
      title: record.title,
      status: record.done ? 'done' : 'open',
    }))
  }
}
export type TodoRecord = {
  readonly id: string
  readonly title: string
  readonly done: boolean
}

/** The todos API owns the todos; this is how the application reaches it. */
export interface TodoGateway {
  list(signal?: AbortSignal): Promise<TodoRecord[]>
}
export type TodoViewModel = {
  readonly id: string
  readonly title: string
  readonly status: 'open' | 'done'
}
import type { TodoGateway, TodoRecord } from '../application/TodoGateway'

export class HttpTodoGateway implements TodoGateway {
  private readonly baseUrl: string

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl
  }

  async list(signal?: AbortSignal): Promise<TodoRecord[]> {
    const response = await fetch(`${this.baseUrl}/api/todos`, { signal })
    if (!response.ok) throw new Error(`GET /api/todos answered ${response.status}`)
    return (await response.json()) as TodoRecord[]
  }
}
import type { TodoViewModel } from '../../application/TodoViewModel'

type TodoItemProps = {
  todo: TodoViewModel
}

export const TodoItem = ({ todo }: TodoItemProps) => (
  <li>
    {todo.title}
    {todo.status === 'done' ? ' (done)' : null}
  </li>
)
